const sketch = (p5obj:any) => {
let P: number = 7; //個数
let S: number = 6; //角の数
let N: number = 4; //回数
let mag: number = 800; //図の大きさ
let outside_curve: boolean = false;
 
p5obj.setup = () =>  {
  p5obj.createCanvas(1000, 1000);
  p5obj.background(0);
  p5obj.ellipseMode(p5obj.CENTER);
  p5obj.smooth();
}
 
p5obj.draw = () =>  {

  p5obj.background(0);
  p5obj.stroke(255);
  p5obj.strokeWeight(1);
  snowFlake();
}
 
const snowFlake = () => {
  let gr: number = - p5obj.TWO_PI / P; // 元の回転角度
  if (outside_curve)
    gr = p5obj.TWO_PI/P;
  let r: number = - p5obj.TWO_PI / S; // 元じゃないやつの回転角度

  let D: number[] = new Array(P).fill([]); 
  for (let i: number = 1; i < P-1; i++)
    D[i] = -gr;
  D[0]=D[P-1]=gr*(P-2)/2;

  let O: number[] = new Array(N).fill([]);

  let x1: number = p5obj.width/2;
  let y1: number = p5obj.height/2-mag/2;
  let x2: number = 0;
  let y2: number = 0;

  let an: number = r/2-p5obj.TWO_PI; 
  let l: number = mag * p5obj.sin(r/2)/p5obj.pow(3, N); //位置
  
  let i:number = 0;
  let k:number = 0;
  let curve_finished: boolean;
  for (i=0; i<S; i++) { // 曲線の数、ポリゴンサイズ
    for (k=0; k<N; k++) // ゼロから作成
      O[k]=0;
    // 曲線ーーーーーーーー
    curve_finished=false;
    k=0;
    while (true) {
      x2=x1+p5obj.cos(an)*l; //横幅
      y2=y1+p5obj.sin(an)*l;  //縦幅
      p5obj.line(x1, y1, x2, y2);
      x1=x2; 
      y1=y2;
      if (curve_finished)  break;

      an = an + D[O[k]];
      O[k]=O[k]+1;

      k=0;
      while (O[k]==P) {
        O[k] = 0;
        k = k + 1;
        if (k==N) {
          curve_finished = true;
          break;
        }
      }
    }
    an = an + r; // 追加の角度
  }
}

};

export default sketch;
