/**
 * Video List
 */
interface VideoListProps {
  videoList: string[];
  thumbList: string[];
}

export const VideoList: React.FC<VideoListProps> = ({ videoList, thumbList }) => {
  const [selectVideoIndex,setSelectVideoIndex] = useState<number>(0);

  // サムネイルがクリックされた時の処理
  const handleThumbClick = (index:number) => {
    setSelectVideoIndex(index);
  };

  // コンポーネントがアンマウントされた時の処理
  useEffect(() => {
    return () => {
      setSelectVideoIndex(0);
    };
  }, []);

  return (
    <div>
      <ul>
        {videoList.map((video, index) => (
          <img className={ (index === selectVideoIndex ) ? "video-thumbnail-selected" : "video-thumbnail"} src={`${sketchImageRoot}${thumbList[index]}`} alt={`Thumbnail for ${video}`} onClick={() => handleThumbClick(index)} />
        ))}
      </ul>
      <Video src={videoList[selectVideoIndex]} />
    </div>
  );
};


