/**
 * .jsからP5を実行 
 * 
 *  folder内のpdeファイルを読み込んでコードブロック表示
 */

const sketchPDERoot: string = process.env.PUBLIC_URL + '/sketch/';
const sketchJSRoot: string = './sketch/';

interface SketchCodeProps
{
  name:string;
  subSource?:string[];
  subFolder?:string;
  isPlayable?:boolean;
  isTwoImages?:boolean; // ２枚の画像を読み込み "_01, _02"
  isGif?:boolean;
}
//export const LinkP: React.FC<LinkProps> = (props) => {
export const SketchCode:  React.FC<SketchCodeProps> = ({name,subSource=null,subFolder,isPlayable=false,isTwoImages=false,isGif=false}) => {
  const [p5Instance, setP5Instance] = useState<any>(null);
  const wrapper = useRef<HTMLDivElement>(null);
  const [strPDEFolderPath, setPDEFolderPath] = useState<string>( (subFolder) ? `${sketchPDERoot}${subFolder}/${name}/` : `${sketchPDERoot}${name}/`);
  const [strJSFolderPath, setJSFolderPath] = useState<string>( (subFolder) ? `${sketchJSRoot}${subFolder}/` : `${sketchJSRoot}`);
  //const [strJSDEJSFullPath, setPDEullPath] = useState<string>(`${sketchPDERoot}${folder}/${folder}.pde`);
  const [sourceProps, setsourceProps] = useState<CodeProps[]>([]);
  const [ isPdeLoaded, setPdeLoaded ] = useState<boolean>(false);
  const [isRunning, setIsRunning] = useState(false);

   // コードブロック
  useEffect(() => {

    const fetchPdeFiles = async () => {

      try {
        // main pde
        {
          let pdeFileFullPath = `${strPDEFolderPath}${name}.pde`;
          console.log(`pdeFileFullPath: ${pdeFileFullPath}`);
          const response = await fetch(`${pdeFileFullPath}`);
          if (!response.ok) {
            throw new Error('Failed to fetch PDE files');
          }
          const pdeFilesText = await response.text(); // テキストデータとして取得
          const props: CodeProps[] = [ { name: `main`, codeText: pdeFilesText } ];
          setsourceProps( props );
        }
        if( subSource )
        {
          for( let i = 0; i < subSource.length; i++ )
          {
            let pdeFileFullPath = `${strPDEFolderPath}${subSource[i]}.pde`;
            console.log(`pdeFileFullPath: ${pdeFileFullPath}`);
            const response = await fetch(`${pdeFileFullPath}`);
            if (!response.ok) {
              throw new Error('Failed to fetch PDE files');
            }
            const pdeFilesText = await response.text(); // テキストデータとして取得
            const props: CodeProps = { name: subSource[i], codeText: pdeFilesText };
            setsourceProps( prevArray => [...prevArray, props ] );
          }
        }
        setPdeLoaded( true );
      } catch (error) {
        console.error('Error fetching PDE files:', error);
      }
    };

    // p5インスタンスをクリーンアップしておく
    setIsRunning(false);
    removeP5Instance();

    fetchPdeFiles();
    
    // ページがアンマウントされるときにクリーンアップ処理を行う
    return () => {
      removeP5Instance();
    };
  }, [name,strPDEFolderPath,subSource]);

  useEffect(() => {
    if (isRunning) {
      startP5Execution();
    } else {
      stopP5Execution();
    }
  }, [isRunning]);


  const toggleP5Execution = () => {
    setIsRunning(!isRunning);
  };

  const createP5Instance = () => {

    // スケッチJSをダイナミックに取得
    let jsFileFullPath = `${strJSFolderPath}${name}`;
    console.log(`jsFileFullPath: ${jsFileFullPath}`);
    const sketch_func = require(`${jsFileFullPath}`).default;
    if (wrapper.current && !p5Instance )
    {
      setP5Instance(new p5(sketch_func,wrapper.current));
    }
  };

  const removeP5Instance = () => {
    if (p5Instance) {
      p5Instance.remove();
      setP5Instance(null);
    }
  };

  const startP5Execution = () => {
    createP5Instance();
  };

  const stopP5Execution = () => {
    removeP5Instance();
  };

  
  return (
    <div>
      {/* isPlayableかつisRunningの場合 */}
      {(isPlayable && isRunning) ? (
        <div className="sketch-canvas" ref={wrapper}></div> //sketch-canvasというクラスのdiv要素
      ) : (
        // それ以外の場合
        <figure className="figure">
          {/* isTwoImagesがtrueの場合 */}
          {isTwoImages ? (
            // ２つの画像を表示
            <>
              <img src={`${strPDEFolderPath}${name}_01.png`} alt={name} />
              <img src={`${strPDEFolderPath}${name}_02.png`} alt={name} />
            </>
          ) : (
            isGif ? (<img src={`${strPDEFolderPath}${name}.gif`} alt={name} />)
                : (<img src={`${strPDEFolderPath}${name}.png`} alt={name} />) 
          )}
        </figure>
      )}

      {/* isPlayableがtrueの場合 */}
      {isPlayable && (
        // PlayまたはStopボタンを表示
        <button onClick={toggleP5Execution}>
          {isRunning ? 'Stop' : 'Play'}
        </button>
      )}

      { isPdeLoaded &&　( <CodeBlock codes={sourceProps} /> ) }
    </div>
  );
};
/**
 * CodeBlockタグに挟まれたコンテンツからコードブロックを表示する
 * 
 *  folder内のpdeファイルを読み込んでコードブロック表示
 */
interface CodeProps
{
  name: string;
  codeText: string;
}
interface CodeBlockProps {
  //code: string;
  codes?: CodeProps[];
  children?: React.ReactNode; // childrenプロパティを含める
}
export const CodeBlock: React.FC<CodeBlockProps> = ({ children=null, codes=null }) => {
  const [expanded, setExpanded] = useState(false);
  const [copyText, setCopyText] = useState('Copy');
  const [hasExpandText, setHasExpandText] = useState<boolean>(false);
  const [activeTab, setActiveTab] = useState<number>( 0 );
  const codeRef = useRef<HTMLElement>(null);
  const [formattedCodes, setFormattedCodes] = useState<CodeProps[]>([]);
  

  // コード隠し
  const toggleExpanded = () => {
    setExpanded(!expanded);
  };

  // コードコピー
  const copyToClipboard = async () => {
    try {

      await navigator.clipboard.writeText(formattedCodes[activeTab].codeText);
      
      setCopyText('Copied!');
      setTimeout(() => {
        setCopyText('Copy');
      }, 2000); // 2秒後にテキストを元に戻す
    } catch (error) {
      console.error('Failed to copy:', error);
    }
  };

  
  function logCharCode(text: string) {
    for (let i = 0; i < text.length; i++) {
        console.log(`Character "${text[i]}" has Unicode code point ${text.charCodeAt(i)}`);
    }
  }

  // 改行コード（\n）のみをカウントする
  function countNewLines(text: string): number {
    const match = text.match(/\n/g);
    return match ? match.length : 0;
  }

  // 2回以上の改行があるかどうかを判定する
  function hasThreeOrMoreNewLines(text: string): boolean {
    return countNewLines(text) >= 2;
  }

  // コード整形
  useEffect(() => {
    
    let initialFormattedCodes: CodeProps[] = [];

    if( children )
    {
      let addProps: CodeProps = { name: 'main', codeText: children.toString() };
      initialFormattedCodes.push(addProps);
    }

    if( codes )
    {
      for( let i = 0; i < codes.length; i++ )
      {
        initialFormattedCodes.push(codes[i]);
      }
    }

    // キャリッジリターン（\r）削除
    for( let i = 0; i < initialFormattedCodes.length; i++ )
    {
      initialFormattedCodes[i].codeText = initialFormattedCodes[i].codeText.replace(/\r/g, '');
    }

    setFormattedCodes( initialFormattedCodes );

  }, [children,codes]);

  // コードブロックの中身をハイライトする
  useEffect(() => {
    
    if( formattedCodes.length > 0 )
    {
      setHasExpandText(hasThreeOrMoreNewLines(formattedCodes[activeTab].codeText));
    }

    if (codeRef.current && formattedCodes.length > 0 ) 
    {
      //console.log("Formatted code:", formattedCodes[activeTab].codeText);
      hljs.highlightElement(codeRef.current);
    }
    
  }, [formattedCodes,activeTab]);


  // Processing言語のハイライトを適用するためのスタイル
  const codeStyle = {
    fontFamily: 'Consolas, monospace', // 使用するフォント
    fontSize: '16px', // フォントサイズ
  };

  /*
  useEffect(() => {
    return () => {
      setFormattedCodes([]); // アンマウント時に formattedCodes を空にする
    };
  }, []);
  */

  return (
    <div className={`code-block ${expanded || !hasExpandText ? '' : 'collapsed'}`} style={{ maxHeight: expanded ? 'none' : '80px' }}>
      <div className="code-buttons">
        { hasExpandText && <button className="code-toggle-button" onClick={toggleExpanded}>{expanded ? 'Show less' : 'Show more'}</button>}
        { <button className="copy-button" onClick={copyToClipboard}>{copyText}</button> }
      </div>
      <div className="tab-buttons">
        { ( formattedCodes.length > 1 ) && formattedCodes.map((file,index) => ( ( index < 2 ) ? // 暫定措置
          <button 
            key={file.name}
            className={activeTab === index ? 'active' : ''}
            onClick={() => setActiveTab(index)}
          >
            {file.name}
          </button> : <></>
        ))}
      </div>
      
      <pre>
        <code ref={codeRef} key={activeTab} style={codeStyle} className="hljs language-processing" >
          {( formattedCodes.length > 0 ) && formattedCodes[activeTab].codeText }
          {/* children ? children : "tes" */}
        </code>
      </pre>
      

    </div>
  );
};
/**
 * スケッチ関連
 * 
 */
 // 出力例: [255, 161, 126]
 export function convertHexToRGB(hex: string): number[] {
  // #を削除して取得
  hex = hex.replace("#", "");

  // R、G、Bのそれぞれを10進数に変換して配列に格納
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);

  return [r, g, b];
}
// 出力例: 16755710
export function convertHexToDecimal(hex: string): number {
  // #を削除して取得
  hex = hex.replace("#", "");

  // 16進数から10進数に変換
  const r = parseInt(hex.substring(0, 2), 16);
  const g = parseInt(hex.substring(2, 4), 16);
  const b = parseInt(hex.substring(4, 6), 16);

  // 10進数に変換したRGB値を組み合わせて1つの数値にする
  const decimalValue = (r << 16) + (g << 8) + b;

  return decimalValue;
}
 // 出力例: "#FFA17E"
export function convertDecimalToHex(decimal: number): string {
  // 10進数をRGB値に分解
  const r = (decimal >> 16) & 255;
  const g = (decimal >> 8) & 255;
  const b = decimal & 255;

  // RGB値を16進数に変換して2桁にする
  const hexR = r.toString(16).padStart(2, "0");
  const hexG = g.toString(16).padStart(2, "0");
  const hexB = b.toString(16).padStart(2, "0");

  // 16進数のRGB値を組み合わせてカラーコードを生成
  const hexColor = "#" + hexR + hexG + hexB;

  return hexColor.toUpperCase(); // カラーコードは大文字に統一する
}
 // 出力例: "numbers[]"
export function convertDecimalToRGB(decimal: number): number[] {
  // 10進数をRGB値に分解
  const r = (decimal >> 16) & 255;
  const g = (decimal >> 8) & 255;
  const b = decimal & 255;

  return [ r, g, b];
}
export function convertRGBToHex(decimal: number): string {
  // 10進数をRGB値に分解
  const r = (decimal >> 16) & 255;
  const g = (decimal >> 8) & 255;
  const b = decimal & 255;

  // RGB値を16進数に変換して2桁にする
  const hexR = r.toString(16).padStart(2, "0");
  const hexG = g.toString(16).padStart(2, "0");
  const hexB = b.toString(16).padStart(2, "0");

  // 16進数のRGB値を組み合わせてカラーコードを生成
  const hexColor = "#" + hexR + hexG + hexB;

  return hexColor.toUpperCase(); // カラーコードは大文字に統一する
}