const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.HSB, 100); //colormodeHSB 100
p5obj.background(0, 0, 0); //background-black
for (var i=0; i<5; i++)
{ //5kai kurikaesu
  p5obj.noStroke(); //sennashi
  p5obj.fill(p5obj.random(0, 8), 100, 100, 30); //red~yellow,alpha30
  p5obj.rect(i*100, 0, 25, 500); //tateline 1
  p5obj.rect(i*100+30, 0, 25, 500); //tateline 2
  p5obj.rect(0, i*100, 500, 25); //yokoline 1
  p5obj.rect(0, i*100+30, 500, 25); //yokoline 2
  for (var k=0; k<100; k++)
  { //100 kai kurikaesu
    p5obj.stroke(10, 100, 100); //line color yellow
    p5obj.strokeWeight(2);
    p5obj.point(k*5, i*100+77); //tensentate
    p5obj.point(i*100+77, k*5); //tensenyoko
  }
}

  };
};

export default sketch;
