const sketch = (p5obj:any) => {
/*
時間経過により回転する歯車
歯車同士がかみ合うことにより、秒針も回転する（ように見えるように作成）
*/


let iQ: number[] = [ 0,-100 ];//歯車の歯の位置
let iC: number[] = [ 255,200,120,70 ];//色

p5obj.setup = () => 
{
p5obj.createCanvas(770,600);
p5obj.frameRate(60);
}


p5obj.draw = () => 
{
  p5obj.translate(p5obj.width/2,p5obj.height/2);//初期位置(ここで全体の位置調整が出来る)
  p5obj.background(iC[1]);
  
  //秒を表す歯車
  p5obj.push();//位置を保存  
  p5obj.translate(210,-180);
  sDeg2();
  p5obj.scale(0.5);
  Haguruma1();
  p5obj.pop();//位置をリセット
  
  //秒の歯車と嚙み合う歯車
  p5obj.push();//位置を保存  
  p5obj.translate(250,-70);
  sDeg1_2();
  p5obj.scale(0.5);
  Haguruma1();
  p5obj.pop();//位置をリセット

  //分の調整歯車
  p5obj.push();//位置を保存 
  p5obj.translate(108,-50); 
  sDeg2();
  p5obj.rotate(p5obj.radians(6));
  p5obj.scale(0.7);
  Haguruma2();
  p5obj.pop();//位置をリセット
  
  //分の歯車
  p5obj.push();//位置を保存 
  p5obj.translate(245,100);
  p5obj.rotate(p5obj.radians(10));//かみ合うように角度調整
  sDeg2();
  p5obj.scale(0.9);
  Haguruma2();
  p5obj.pop();//位置をリセット
  
  //分の歯車 + 時の歯車
  p5obj.push();//位置を保存 
  p5obj.translate(245,98);
  p5obj.rotate(p5obj.radians(10));
  sDeg1_3();
  p5obj.scale(0.79);
  Haguruma3();
  p5obj.pop();//位置をリセット
  
  
  //時の調整歯車
  p5obj.push();//位置を保存 
  p5obj.translate(10,130);
 p5obj.rotate(p5obj.radians(10));
  sDeg1_2();
  p5obj.scale(1);
  Haguruma3();
  p5obj.pop();//位置をリセット
  
  //時の歯車
  p5obj.push();//位置を保存 
  p5obj.translate(-180,-80);
  p5obj.rotate(p5obj.radians(10));
  sDeg2();
  p5obj.scale(1.4);
  Haguruma3();
  p5obj.pop();//位置をリセット
  
  //時の歯車 + 分の歯車
  p5obj.push();//位置を保存 
  p5obj.translate(-180,-80);   
  p5obj.scale(1.1);
  sDeg1_4();
  Haguruma2();
  p5obj.pop();//位置をリセット
  
  //秒針
  p5obj.push();//位置を保存  
  p5obj.translate(210,-180);
  sDeg1();
  p5obj.scale(0.5);
  Hari1();
  p5obj.pop();//位置をリセット
  
  //分針
  p5obj.push();//位置を保存  
  p5obj.translate(245,98);
  mDeg();
  p5obj.scale(0.9);
  Hari1();
  p5obj.pop();//位置をリセット
   
  //時針
  p5obj.push();//位置を保存  
  p5obj.translate(-180,-80);
  hDeg();
  p5obj.scale(1.2);
  Hari2();
  p5obj.pop();//位置をリセット
}




//歯車の回転（右回転）


const sDeg1 = () => {  
  let iSecond: number = p5obj.second();
  p5obj.rotate(p5obj.radians(6*iSecond));
}

const sDeg1_2 = () => {  
  let iSecond: number = p5obj.second();
  p5obj.rotate(p5obj.radians(3*iSecond));
}

const sDeg1_3 = () => {  
  let iSecond: number = p5obj.second()/2;
  p5obj.rotate(p5obj.radians(3*iSecond));
}

const sDeg1_4 = () => {  
  let iSecond: number = p5obj.second()/3;
  p5obj.rotate(p5obj.radians(3*iSecond));
}

const mDeg = () => {  
  let iMinute: number = p5obj.minute();
  p5obj.rotate(p5obj.radians(6*iMinute));
}

const hDeg = () => {  
  let iHour: number = p5obj.hour();
  p5obj.rotate( p5obj.radians( 30 * iHour  ) );
}


//歯車の回転（反時計回り）
const sDeg2 = () => {  
  let iSecond: number = p5obj.second();
  p5obj.rotate(-p5obj.radians(3*iSecond ));
}





//針の描写


const Hari1 = () => {
  p5obj.noStroke();
  //中の円の描写
  p5obj.fill(iC[2]);
  p5obj.circle(0,0,180);
  p5obj.fill(iC[0]);
  p5obj.circle(0,-50,75);
  p5obj.fill(iC[2]);
  p5obj.circle(0,-50,65);
  p5obj.fill(iC[0]);
  p5obj.circle(0,0,150);
  p5obj.fill(iC[2]);
  p5obj.circle(0,0,140);
  p5obj.fill(iC[1]);
  p5obj.circle(0,0,100);
  p5obj.fill(iC[0]);
  p5obj.circle(0,0,50);
  
  //針の描写
  p5obj.fill(iC[0]);
  p5obj.quad(iQ[0]-2,iQ[1]-50,iQ[0]+2,iQ[1]-50,iQ[0]+4,iQ[1]+75,iQ[0]-4,iQ[1]+75);
  
}

const Hari2 = () => {
  p5obj.noStroke();
  //中の円の描写
  p5obj.fill(iC[2]);
  p5obj.circle(0,0,180);
  p5obj.fill(iC[0]);
  p5obj.circle(0,-50,75);
  p5obj.fill(iC[2]);
  p5obj.circle(0,-50,65);
  p5obj.fill(iC[0]);
  p5obj.circle(0,0,150);
  p5obj.fill(iC[2]);
  p5obj.circle(0,0,140);
  p5obj.fill(iC[1]);
  p5obj.circle(0,0,100);
  p5obj.fill(iC[0]);
  p5obj.circle(iQ[0],iQ[1]+70,25);
  p5obj.circle(0,0,50);
  
  //針の描写
  p5obj.fill(iC[0]);
  p5obj.quad(iQ[0]-2,iQ[1]-60,iQ[0]+2,iQ[1]-60,iQ[0]+10,iQ[1]+90,iQ[0]-10,iQ[1]+90);
  
}




//歯車の描写

const Haguruma1 = () => {  
  p5obj.noStroke();
  p5obj.fill(iC[3]);
  p5obj.circle(0,0,200); 
  p5obj.fill(iC[1]);
  p5obj.circle(0,0,150);
  p5obj.fill(iC[3]);
   for(let i: number = 0; i<24; i ++)
  {
    p5obj.quad(iQ[0]-3,iQ[1]-30,iQ[0]+3,iQ[1]-30,iQ[0]+5,iQ[1]+50,iQ[0]-5,iQ[1]+50);//歯の描写
    p5obj.rotate(p5obj.radians(15));
  }
  p5obj.fill(iC[3]);
  p5obj.circle(0,0,120);
  p5obj.fill(iC[1]);
  p5obj.circle(0,0,80);
 
}


const Haguruma2 = () => {  
  p5obj.noStroke();
  p5obj.fill(iC[2]);
   for(let i: number = 0; i<12; i ++)
  {
    p5obj.quad(iQ[0]-3,iQ[1]-25,iQ[0]+3,iQ[1]-25,iQ[0]+5,iQ[1],iQ[0]-5,iQ[1]);//歯の描写
    p5obj.rotate(p5obj.radians(30));
    p5obj.square(iQ[0]-15,iQ[1]-10,30);
  }
  p5obj.circle(0,0,205);
  p5obj.fill(iC[1]);
  p5obj.circle(0,0,100);
}


const Haguruma3 = () => { 
  p5obj.noStroke();
  p5obj.fill(iC[3]);
  for(let i: number = 0; i<12; i ++)
  {
    p5obj.quad(iQ[0]-10,iQ[1]-15,iQ[0]+10,iQ[1]-15,iQ[0]+15,iQ[1],iQ[0]-15,iQ[1]);//歯の描写
    p5obj.quad(iQ[0]+3,iQ[1]-30,iQ[0]-3,iQ[1]-30,iQ[0]-10,iQ[1]-14,iQ[0]+10,iQ[1]-14);//歯の描写(小さくなるところ)
    p5obj.rotate(p5obj.radians(30));
  }
  p5obj.circle(0,0,205);
  p5obj.fill(iC[1]);
  p5obj.circle(0,0,100);
}

};

export default sketch;
