const sketch = (p5obj:any) => {
/**
 second: star orange
 minute: star green
 hour: rocket
*/

p5obj.setup = () => 
{
  p5obj.createCanvas( 650, 650 );
  p5obj.colorMode(p5obj.RGB, 255, 255, 255, 100 );
  p5obj.background( 9, 34, 55, 30 ); //navy
  p5obj.frameRate( 20 );
}

p5obj.draw = () => 
{
  //refresh
  p5obj.noStroke();
  p5obj.fill( 9, 34, 55, 25 );
  p5obj.rect( 0, 0, 650, 650 );

  p5obj.translate( p5obj.width/2, p5obj.height/2 );
    
  let s: number = p5obj.second();
  let m: number = p5obj.minute();
  let h: number = p5obj.hour();
  
  //second
  p5obj.push();
  p5obj.rotate( p5obj.radians(s*(360/60)) );
  for( let iX: number = 0; iX<500; iX+=5 ) 
  {
    p5obj.rotate( p5obj.radians(20) );
    p5obj.fill( 230 );
    p5obj.circle( 5, 100, 5 );
  }
  p5obj.pop();
  
  //minute
  p5obj.push();
  p5obj.rotate( p5obj.radians(m*(360/60)) );
  for( let iX: number = 0; iX<500; iX+=5 )
  {
    p5obj.rotate( p5obj.radians(20) );
    p5obj.fill( 230 );
    p5obj.circle( 5, 180, 8 );
  }
  p5obj.pop();
  
  //hour
  p5obj.push();
  for( let iX: number = 0; iX<600; iX+=5 )
  {
    p5obj.rotate( p5obj.radians(20) );
    p5obj.fill( 230 );
    p5obj.circle( 5, 280, 10 );
  }
  p5obj.pop();
  
  //centor:star
  p5obj.stroke( 230 );
  p5obj.fill( 0, 100, 200 ); //blue
  p5obj.circle( 0, 0, 60 );
  p5obj.fill( 120, 210, 250 ); //light blue
  p5obj.ellipse( 0, 0, 100, 12 );
  
  //hour:rocket
  p5obj.push();
  p5obj.rotate( p5obj.radians(h*(360/12)) );
  p5obj.translate( 0, -280 );
  p5obj.rotate( p5obj.radians(270) );
  
  p5obj.noStroke();
  
  //rocket
  p5obj.fill( 253, 208, 0 ); //yellow
  p5obj.beginShape();
  p5obj.vertex(   0,  40 );
  p5obj.vertex( -20,  30 );
  p5obj.vertex( -20,   0 );
  p5obj.vertex( -30, -10 );
  p5obj.vertex( -30, -40 );
  p5obj.vertex( -20, -30 );
  p5obj.vertex(  20, -30 );
  p5obj.vertex(  30, -40 );
  p5obj.vertex(  30, -10 );
  p5obj.vertex(  20,   0 );
  p5obj.vertex(  20,  30 );
  p5obj.endShape( p5obj.CLOSE );
  
  //window
  p5obj.fill( 120, 210, 250 ); //light blue
  p5obj.circle( 0, 0, 25 );
  
  //fire
  p5obj.fill( 241, 141, 0 ); //orange
  p5obj.ellipse( 0, -70, 35, 50 );
  p5obj.fill( 200, 0, 30 ); //red
  p5obj.ellipse( 0, -62, 20, 35 );
  p5obj.pop();
  
  //minute:star
  p5obj.push();
  p5obj.rotate( p5obj.radians(m*(360/60)) );
  p5obj.translate( -5.5, -175 );
  p5obj.rotate( p5obj.radians(90) );
  
  p5obj.stroke( 255 );
  p5obj.fill( 170, 240, 120 ); //green
  p5obj.circle( 0, 0, 60 );
  p5obj.fill( 253, 208, 0 ); //yellow
  p5obj.ellipse( 0, 0, 15, 100 );
  p5obj.pop();
  
  //second:star
  p5obj.push();
  p5obj.rotate( p5obj.radians(s*(360/60)) );
  p5obj.translate( -7, -100 );
  
  p5obj.noStroke();
  p5obj.fill( 241, 141, 0 ); //orange
  p5obj.circle( 0, 0, 28 );
  p5obj.pop();
}

};

export default sketch;
