const sketch = (p5obj:any) => {
//プリント回路風の模様です
let R: number = 0;

let X: number = 0;

p5obj.setup = () => 
{
  p5obj.background(0);
  p5obj.strokeWeight(2);
  p5obj.stroke(93, 187, 173);
  p5obj.blendMode(p5obj.SCREEN);
  p5obj.createCanvas( 1000, 1000 );
  p5obj.translate(500, 500);
  p5obj.rectMode(p5obj.CENTER);
  //無理矢理四方向から描画する
  for (let iX: number = -500; iX<500; iX+=p5obj.random(1, 10))
  {
    Circuit( iX, -500, p5obj.random(50, 100), -90, 3 );
  }
  p5obj.rotate(p5obj.radians(90));
  for (let iX: number = -500; iX<500; iX+=p5obj.random(1, 10))
  {
    Circuit( iX, -500, p5obj.random(50, 100), -90, 3 );
  }
  p5obj.rotate(p5obj.radians(90));
  for (let iX: number = -500; iX<500; iX+=p5obj.random(1, 10))
  {
    Circuit( iX, -500, p5obj.random(50, 100), -90, 3 );
  }
  p5obj.rotate(p5obj.radians(90));
  for (let iX: number = -500; iX<500; iX+=p5obj.random(1, 10))
  {
    Circuit( iX, -500, p5obj.random(50, 100), -90, 3 );
  }
}
const Circuit = (f1X: number, f1Y: number, fBer: number, fR: number, iLevel: number) => {
  let f2X: number = f1X ;
  let f2Y: number = f1Y + fBer;
  //再帰一回（直進→左右斜め→直進）の内、左右をランダムに決める
  X = p5obj.random(2);
  if (X<=1)//左に折れる
  {
    let f3X: number = f2X - fBer/2 * p5obj.cos(p5obj.radians(45));
    let f3Y: number = f2Y + fBer/2 * p5obj.cos(p5obj.radians(45));
    let f4X: number = f3X;
    let f4Y: number = f3Y + fBer;
    p5obj.line( f1X, f1Y, f2X, f2Y );
    p5obj.line(f2X, f2Y, f3X, f3Y);
    p5obj.line(f3X, f3Y, f4X, f4Y);
    if ( iLevel > 1 )
    {
      Circuit( f4X, f4Y, fBer * 0.5, fR, iLevel - 1 );
    } else
    {
      p5obj.fill(0);
      p5obj.circle(f4X, f4Y, 8);
    }
  } else //右に折れる
  {
    let f3X: number = f2X + fBer/2 * p5obj.cos(p5obj.radians(45));
    let f3Y: number = f2Y + fBer/2 * p5obj.cos(p5obj.radians(45));
    let f4X: number = f3X;
    let f4Y: number = f3Y + fBer;
    p5obj.line( f1X, f1Y, f2X, f2Y );
    p5obj.line(f2X, f2Y, f3X, f3Y);
    p5obj.line(f3X, f3Y, f4X, f4Y);
    if ( iLevel > 1 )
    {
      Circuit( f4X, f4Y, fBer * 0.5, fR, iLevel - 1 );
    } else
    {
      p5obj.fill(0);
      p5obj.circle(f4X, f4Y, 8);
    }
  }
}

};

export default sketch;
