const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.colorMode(p5obj.RGB, 500, 500, 500);
p5obj.background(500, 0, 0);
p5obj.strokeWeight(2.5);
p5obj.stroke(500, 500, 500);
for (var x=0; x<600; x=x+50)
{
  for (var y=0; y<600; y=y+100)
  {
    p5obj.quad(x+0, -20+y,
      x+0, y+30,
      x+10, y+50,
      x+10, y);
    p5obj.quad(x+15, y+50,
      x+15, y,
      x+25, -20+y,
      x+25, y+30);
    p5obj.quad(x+25, y+30,
      x+25, y+80,
      x+35, y+100,
      x+35, y+50);
    p5obj.quad(x+40, y+100,
      x+40, y+50,
      x+50, y+30,
      x+50, y+80);
  }
}
for (var x=0; x<600; x=x+50)
{
  for (var y=0; y<600; y=y+100)
  {
    p5obj.line(x+12, y+55, x+12, y+100);
    p5obj.line(x+37, y+0, x+37, y+50);
  }
}

  };
};

export default sketch;
