const sketch = (p5obj:any) => {
let iDraw: number = 0;
    // 描画フラグ(0or1)
let iImageNo: number = 0;
   // 画像番号


p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  iDraw=1;
  //p5obj.noLoop();
}

p5obj.draw = () => 
{
  if( iDraw == 1 )
  {
    p5obj.background(240,240,255);//少しだけ青みがかった白
    shikaku(0,0,1000,4);//(a,b,m,x)の初期値
    
    iDraw = 0;  // 描画フラグを0へ
  }
}

const shikaku = (a: number, b: number, m: number, x: number) => {
  p5obj.noStroke();
  p5obj.fill(240,240,255);
  p5obj.rect(a,b,m,m);//最初は(0,0,1000,1000)の正方形
  moyou(a,b,m);//最初は(0,0,1000)が（A ,B,C）の初期値
  let c: number = m/2;
  x--;
  let d: number = p5obj.map(x, 0, 3, 0.3, 0);//xが0,1,2,3の時、dは0.3,0.2,0.1,0
  
  if (x >= 0) //xが3から0までの4回
  {
    if (p5obj.random(1) >= d) //０以上１未満のランダム数がdより大きい時4分割する(初めは必ず4分割される)
    {
      shikaku(a, b, c, x);//左上、mの値が半分になる(以下同様)
      shikaku(a+c, b, c, x);//右上、
      shikaku(a+c, b+c, c, x);//右下
      shikaku(a, b+c, c, x);//左下
    }
  }
  
}

const moyou = (A: number, B: number, C: number) => {
  p5obj.stroke(100,100,255);//青
  p5obj.strokeWeight(7);
  p5obj.strokeCap(p5obj.SQUARE);
  p5obj.noFill();
  let D: number = 2*C;//半径をrectの幅にする  
  let E: number = p5obj.random(4);

  if(C==500)//正方形のサイズが500の時
  {
    if(E==0)//25%の確率で
    {
       for (let nami: number = 0; nami<32; nami++)//32本の円弧を
      {
        p5obj.arc(A,B,D,D,p5obj.radians(0),p5obj.radians(90),p5obj.OPEN);//左上を中心として描く
        D=D-C/16;
       }
    }
    else if(E==1)
    {
      for (let nami: number = 0; nami<32; nami++)
      {
        p5obj.arc(A+C,B,D,D,p5obj.radians(90),p5obj.radians(180),p5obj.OPEN);//右上を中心として描く
        D=D-C/16;
      }
    }
    else if(E==2)
    {
      for (let nami: number = 0; nami<32; nami++)
      {
        p5obj.arc(A+C,B+C,D,D,p5obj.radians(180),p5obj.radians(270),p5obj.OPEN);//右下を中心として描く
        D=D-C/16;
      }
    }
    else if(E==3)
    {
      for (let nami: number = 0; nami<32; nami++)
      {
        p5obj.arc(A,B+C,D,D,p5obj.radians(270),p5obj.radians(360),p5obj.OPEN);//左下を中心として描く
        D=D-C/16;
      }
    }
  }
  
  else if(C==250)//正方形のサイズが250の時
  {
    if(E==0)
    {
       for (let nami: number = 0; nami<16; nami++)//16本の円弧を
      {
        p5obj.arc(A,B,D,D,p5obj.radians(0),p5obj.radians(90),p5obj.OPEN);//左上を中心として描く
        D=D-C/8;
       }
    }
     else if(E==1)
    {
      for (let nami: number = 0; nami<16; nami++)
      {
        p5obj.arc(A+C,B,D,D,p5obj.radians(90),p5obj.radians(180),p5obj.OPEN);//右上を中心として描く
        D=D-C/8;
      }
    }
    else if(E==2)
    {
      for (let nami: number = 0; nami<16; nami++)
      {
        p5obj.arc(A+C,B+C,D,D,p5obj.radians(180),p5obj.radians(270),p5obj.OPEN);//右下を中心として描く
        D=D-C/8;
      }
    }
    else if(E==3)
    {
      for (let nami: number = 0; nami<16; nami++)
      {
        p5obj.arc(A,B+C,D,D,p5obj.radians(270),p5obj.radians(360),p5obj.OPEN);//左下を中心として描く
        D=D-C/8;
      }
    }  
  }
  
  else if(C==125)//正方形のサイズが125の時
  {
    if(E==0)
    {
       for (let nami: number = 0; nami<8; nami++)//8本の円弧を
      {
        p5obj.arc(A,B,D,D,p5obj.radians(0),p5obj.radians(90),p5obj.OPEN);//左上を中心として描く
        D=D-C/4;
       }
    }
     else if(E==1)
    {
      for (let nami: number = 0; nami<8; nami++)
      {
        p5obj.arc(A+C,B,D,D,p5obj.radians(90),p5obj.radians(180),p5obj.OPEN);//右上を中心として描く
        D=D-C/4;
      }
    }
    else if(E==2)
    {
      for (let nami: number = 0; nami<8; nami++)
      {
        p5obj.arc(A+C,B+C,D,D,p5obj.radians(180),p5obj.radians(270),p5obj.OPEN);//右下を中心として描く
        D=D-C/4;
      }
    }
    else if(E==3)
    {
      for (let nami: number = 0; nami<8; nami++)
      {
        p5obj.arc(A,B+C,D,D,p5obj.radians(270),p5obj.radians(360),p5obj.OPEN);//左下を中心として描く
        D=D-C/4;
      }
    }  
  }
  
  else//その他の正方形のサイズ（62.5）の時
  {
    if(E==0)
    {
       for (let nami: number = 0; nami<4; nami++)//4本の円弧を
      {
        p5obj.arc(A,B,D,D,p5obj.radians(0),p5obj.radians(90),p5obj.OPEN);//左上を中心として描く
        D=D-C/2;
       }
    }
     else if(E==1)
    {
      for (let nami: number = 0; nami<4; nami++)
      {
        p5obj.arc(A+C,B,D,D,p5obj.radians(90),p5obj.radians(180),p5obj.OPEN);//右上を中心として描く
        D=D-C/2;
      }
    }
    else if(E==2)
    {
      for (let nami: number = 0; nami<4; nami++)
      {
        p5obj.arc(A+C,B+C,D,D,p5obj.radians(180),p5obj.radians(270),p5obj.OPEN);//右下を中心として描く
        D=D-C/2;
      }
    }
    else if(E==3)
    {
      for (let nami: number = 0; nami<4; nami++)
      {
        p5obj.arc(A,B+C,D,D,p5obj.radians(270),p5obj.radians(360),p5obj.OPEN);//左下を中心として描く
        D=D-C/2;
      }
    }    
  }
  
}

const keyPressed = () => {
  if (p5obj.key == p5obj.ENTER)
  {
    iDraw = 1;
  }
}

const mouseClicked = () => {
  if( p5obj.mouseButton == p5obj.RIGHT )
  {
    p5obj.save( "sakuhin" + iImageNo + ".png" );
    iImageNo++;
  }
}

};

export default sketch;
