              <CodeBlock>{'int iFrame = 0;\nfloat fX = 0;\nfloat fY = 120;\n\nvoid setup()\n{\n  size( 400, 200 );\n}\n\nvoid draw()\n{\n  background( 204 );\n  \n  drawBB8();\n  \n  updateBB8();\n}\n\nvoid drawBB8()\n{\n  pushMatrix();\n  \n  translate( fX, fY );\n  \n  circle( 0, 0, 40 );\n  arc( 0, -20, 28, 28, radians( -180 ), radians( 0 ), PIE );\n  \n  popMatrix();\n}\n\nvoid updateBB8()\n{\n  if( iFrame < 50 )       // 右へ\n  {\n    fX += 3;\n    iFrame++;\n  }\n  else if( iFrame < 140 )  // ゆっくり右へ\n  {\n    fX += 1;\n    iFrame++;\n  }\n  else if( iFrame < 200 )  // 右へ\n  {\n    fX += 4;\n    iFrame++;\n  }\n  else                    // アニメリセット\n  {\n    // 初期位置へ\n    fX = 0;\n    fY = 120;\n    iFrame = 0;\n  }\n}'}</CodeBlock>
