const sketch = (p5obj:any) => {
/**

棒人間が24時間歩き続ける時計
秒で棒人間が歩き、分で雲、時で太陽・月などが変化していく

*/

let iRatateDegS: number;             // 太陽の回転角
let iRatateDegM: number;             // 月の回転角

p5obj.setup = () => 
{
  p5obj.createCanvas(600,450);
  p5obj.colorMode(p5obj.RGB);
  p5obj.frameRate(30);
  iRatateDegS = 0;
  iRatateDegM = 0;
}

p5obj.draw = () => 
{
  let s: number = p5obj.second();//秒数を取得
  let m: number = p5obj.minute();//分
  let h: number = p5obj.hour();//時間
  
  if( h < 24 )//18~24時の間
  {
    //背景
    p5obj.fill( 40, 40, 112 );//紺
    p5obj.noStroke();
    p5obj.rect( 0, 0, p5obj.width, p5obj.height );
  
    // 月の描画
    iRatateDegM  = 180/11*( h - 18 ); //1時間180/11度ごと回転（月）
    p5obj.fill( 255, 255, 0 );
    p5obj.circle( 300-280*p5obj.cos(p5obj.radians(iRatateDegM)), 400-280*p5obj.sin(p5obj.radians(iRatateDegM)), 70 );
    p5obj.fill( 40, 40, 112 );
    p5obj.circle( 320-280*p5obj.cos(p5obj.radians(iRatateDegM)), 390-280*p5obj.sin(p5obj.radians(iRatateDegM)), 70 );
  }
  
  if( h < 18)//6~18時の間
  { 
    //背景
    p5obj.fill( 30, 175, 255 );//青
    p5obj.noStroke();
    p5obj.rect( 0, 0, p5obj.width, p5obj.height );
    
    //太陽の描画
    iRatateDegS  = 180/11*( h - 6 ); //1時間180/11度ごと回転（太陽）
    p5obj.fill( 255, 255, 180 );
    p5obj.circle( 300-280*p5obj.cos(p5obj.radians(iRatateDegS)), 400-280*p5obj.sin(p5obj.radians(iRatateDegS)), 65 );
  }
  
  if( h < 6)//0~6時の間
  {
    p5obj.fill( 40,  40, 112 );
    p5obj.noStroke();
    p5obj.rect( 0, 0, p5obj.width, p5obj.height ); //紺の背景
    
    // 月の描画
    iRatateDegM  = 180/11*(h+6); //1時間180/11度ごと回転（月）
    p5obj.fill( 255, 255, 0 );
    p5obj.circle( 300-280*p5obj.cos(p5obj.radians(iRatateDegM)), 400-280*p5obj.sin(p5obj.radians(iRatateDegM)), 70 );
    p5obj.fill( 40, 40, 112 );
    p5obj.circle( 320-280*p5obj.cos(p5obj.radians(iRatateDegM)), 390-280*p5obj.sin(p5obj.radians(iRatateDegM)), 70 );
  }
 
  //1分ごと左に動く雲
  p5obj.fill(255);
  p5obj.ellipse( 600-10*m, 200, 80, 45);
  p5obj.ellipse( 600-10*m-35, 205, 40, 25);
  p5obj.ellipse( 600-10*m-30, 195, 25, 25);
  p5obj.ellipse( 600-10*m-10, 180, 40, 45);
  p5obj.ellipse( 600-10*m+40, 208, 40, 20);
   
   //地面
  p5obj.fill(0);
  p5obj.rect( 0, 400, 600, 450 );
  
  //1秒ずつ右に進み1分間で右端に到達する棒人間
  p5obj.stroke(0);
  if( s%2 == 0 )//偶数秒の棒人間
  {
    p5obj.strokeWeight(1.6);
    p5obj.line( 10*(s+1), 380, 10*s, 400 );
    p5obj.line( 10*(s+1), 380, 10*(s+2), 400 );
    p5obj.line( 10*(s+1), 360, 10*s, 380 );
    p5obj.line( 10*(s+1), 360, 10*(s+2), 380 );
    p5obj.circle(10*(s+1), 352, 16 );
    p5obj.strokeWeight(2);
    p5obj.line( 10*(s+1), 360, 10*(s+1), 380 );
  }
  else//奇数秒の棒人間
  {
    p5obj.strokeWeight(2);
    p5obj.line( 10*(s+1), 359, 10*(s+1), 400 );
    p5obj.circle(10*(s+1), 351, 16 );
  }
}

};

export default sketch;
