const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 1000);
  p5obj.background(0);
  p5obj.smooth();
  p5obj.frameRate(1);
}



p5obj.draw = () => 
{
  p5obj.translate(p5obj.width/2, p5obj.height/2); // 原点を画面の中心に移動

  p5obj.noStroke();//画面をリセット
  p5obj.fill(0, 1);
  p5obj.rect(-500, -500, 1000, 1000);

  let s: number = p5obj.second();//秒数を取得
  let m: number = p5obj.minute();//分
  let h: number = p5obj.hour();//時間


  //それぞれの針に対応するオブジェクトを描画する
  p5obj.push();

  //時対応の円
  p5obj.rotate(p5obj.radians(h*(360/12)));//時針が動く角度
  p5obj.rotate(p5obj.radians(165));//12時方向スタート
  p5obj.stroke(255);
  p5obj.circle(10, 10, 30);

  p5obj.pop();



  //分対応の四角形
  p5obj.push();

  p5obj.rotate(p5obj.radians(m*(360/60)));//分針が動く角度
  p5obj.rotate(p5obj.radians(165));//12時方向スタート
  p5obj.stroke(255);
  p5obj.quad(30, 30, 50, 40, 70, 70, 40, 50);

  p5obj.pop();


  //秒対応
  p5obj.push();

  p5obj.rotate(p5obj.radians(s*(360/60)));//秒針が動く角度
  p5obj.rotate(p5obj.radians(225));//12時方向スタート
  p5obj.stroke(255);
  p5obj.rect(80, 80, 80, 80);
  p5obj.quad(180, 180, 200, 210, 320, 320, 210, 200);
  p5obj.point(170, 170);

  p5obj.pop();
}

};

export default sketch;
